"""Derives Test-GrenadeBoundGuard-v1273.ps1 from Test-PairedVictim-v1248l.ps1 (product controller on the Dunwall fixture,
checkpoint restoration) for stage 4 (#14): a host grenade on a combat-bound guard. Before 1214w the host capture
suppressed every damage it could not replay (explosion_grenade) and retired the guard's channel, so a host grenade did
not hurt a bound guard. With both peers' combat sessions active, the host takes one native grenade from the lab item
fixture (coop_grenade_fixture), draws it, faces the upper-floor tutorial guard 2 from a few metres and throws (LT held,
native release). Both windows are filmed. Pass (runtime): the guard's host health drops (or it dies) and the client's
replica ends in the same state (HostWorld commit, or Dead after a lethal blast)."""
from pathlib import Path
P = Path(__file__).resolve().parent
s = P.joinpath('Test-PairedVictim-v1248l.ps1').read_bytes().decode('utf-8'); nl = '\r\n' if '\r\n' in s else '\n'
lines = s.split(nl)
def idx(prefix, start=0):
    for i in range(start, len(lines)):
        if lines[i].startswith(prefix): return i
    raise AssertionError(prefix)
main = idx('try{')
tail = idx('}catch{$failure=$_.Exception.Message;Save "$out/failure.json"')
head = lines[:main]
head[0] = "param([ValidatePattern('^[a-z0-9-]+$')][string]$Take='grenade-bound-guard-v1273a',[string]$Candidate='candidate-npc-combat-v1214w',[double]$Distance=5,[int]$Pitch=10,[int]$Attempts=2)"
head = [head[0], '# 1273 (stage 4, #14, 1214w): a host grenade on a combat-bound guard. Generated by make_grenade_bound_guard_v1273.py from 1248l.'] + [l for l in head[1:] if not l.startswith('# ')]
setup = lines[main:idx(' foreach($source in $Sources)')]
setup = [l.replace("operation='PairedVictim1248l'", "operation='GrenadeBoundGuard1273'").replace('sources=$Sources', 'distance=$Distance;pitch=$Pitch') for l in setup]
body = r''' $row=[ordered]@{passed=$false;failure=$null;checks=[Collections.Generic.List[string]]::new()};$captures=[Collections.Generic.List[object]]::new()
 try{
  $dirty=$true;Arm
  foreach($q in 'host','client'){C $q 'setviewpos -33 -153 68.1 90 0'}
  $live=WaitLive 'armed' 45000;if(!$live.ok){throw 'Partner presentation not live after arming'}
  $w=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 400;$hc=S host '.npc-combat.json';$cc=S client '.npc-combat.json';$ok=$hc.result-eq'active_native_melee'-and$cc.result-eq'active_native_melee'}while(!$ok-and$w.ElapsedMilliseconds-lt20000)
  if(!$ok){throw "Combat session not active on both peers (host $($hc.result), client $($cc.result))"};$row.checks.Add('Combat session active on both peers')
  $tries=[Collections.Generic.List[object]]::new();$hurt=$false
  for($a=0;$a-lt$Attempts-and!$hurt;$a++){
   $g=Guard host;$og=Guard client;$row.guardHost=$g.handle;$row.guardClient=$og.handle
   $before=[ordered]@{host=(Q host '--health' $g.handle).current;client=(Q client '--health' $og.handle).current}
   C host 'coop_grenade_fixture 12000';$fw=[Diagnostics.Stopwatch]::StartNew()
   do{Start-Sleep -Milliseconds 50;$f=S host '.grenade-fixture.json'}while($f.result-ne'native_grenade_ready'-and$fw.ElapsedMilliseconds-lt2500)
   if($f.result-ne'native_grenade_ready'){throw "Grenade fixture not ready ($($f.result))"}
   I host X 1500;Start-Sleep -Milliseconds 1900;I host X 650;Start-Sleep -Milliseconds 1350
   $held=Q host '--player-grenade';if(!$held.equipped-or$held.quantity-ne1){throw 'Native grenade not selected'}
   # Stand on the line from the fixture's open spot (-33,-153) to the guard, $Distance m from it, facing it.
   $g=Guard host;$vx=-33-[double]$g.position[0];$vy=-153-[double]$g.position[1];$vl=[Math]::Max([Math]::Sqrt($vx*$vx+$vy*$vy),0.01);$fx=-$vx/$vl;$fy=-$vy/$vl;$yaw=[Math]::Atan2($fy,$fx)*180/[Math]::PI
   C host ('setviewpos {0} {1} {2} {3} 0' -f (F ([double]$g.position[0]-$Distance*$fx)),(F ([double]$g.position[1]-$Distance*$fy)),(F ([double]$g.position[2]+1.7)),$yaw.ToString('F4',$inv));Start-Sleep -Milliseconds 500
   try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role host -Pitch $Pitch -Quick|Out-Null}catch{}
   foreach($r in 'host','client'){$hwnd=(Get-Process -Id $pids[$r]).MainWindowHandle.ToInt64()
    $captures.Add((Start-Process (Get-Command ffmpeg).Source -ArgumentList @('-hide_banner','-loglevel','warning','-nostdin','-f','lavfi','-i',"gfxcapture=hwnd=${hwnd}:capture_cursor=0:max_framerate=30:width=-2:height=-2,hwdownload,format=bgra",'-t','9','-an','-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p','-fps_mode','passthrough','-movflags','+faststart',"$out/throw$a-$r.mp4") -WindowStyle Hidden -RedirectStandardError "$out/throw$a-$r-capture.log" -PassThru))}
   Start-Sleep -Milliseconds 400
   & "$lab/Send-D2Input.ps1" -Role host -LeftTrigger 255 -DurationMs 1300|Out-Null
   $samples=[Collections.Generic.List[object]]::new();$sw=[Diagnostics.Stopwatch]::StartNew()
   do{Start-Sleep -Milliseconds 300;$hh=try{Q host '--health' $g.handle}catch{$null};$ch=try{Q client '--health' $og.handle}catch{$null}
    $samples.Add([pscustomobject]@{ms=$sw.ElapsedMilliseconds;host=$hh.current;client=$ch.current;hostSuppressed=$hh.ownerSuppressed;clientSuppressed=$ch.ownerSuppressed})}while($sw.ElapsedMilliseconds-lt6500)
   foreach($c in @($captures)){try{if(!$c.WaitForExit(30000)){Stop-Process -Id $c.Id}}catch{}};$captures.Clear()
   $after=[ordered]@{host=$(try{(Q host '--health' $g.handle).current}catch{$null});client=$(try{(Q client '--health' $og.handle).current}catch{$null})}
   $hc=S host '.npc-combat.json';$cc=S client '.npc-combat.json';$hs=S host '.npc-stream.json';$cs=S client '.npc-stream.json'
   $tries.Add([pscustomobject]@{attempt=$a;before=$before;after=$after;samples=@($samples);
    host=($hc|Select-Object result,hostNativePassed,hostNativeLast,hostWorldCommitted,committed,deaths,lastRetire);client=($cc|Select-Object result,hostWorldApplied,followSubtractions,applied,deaths,lastRetire);
    hostRelevance=($hs.relevance|Select-Object deadReconciled,deadSent);clientRelevance=($cs.relevance|Select-Object clientDeadApplied,clientDeadAlready,clientDeadRefused,clientDeadLast)})
   Save "$out/throws.json" @($tries)
   $hurt=($null-eq$after.host)-or([double]$after.host-lt[double]$before.host)
  }
  foreach($q in 'host','client'){foreach($suffix in '.npc-stream.json','.npc-combat.json','.grenade-fixture.json'){try{Copy-Item -LiteralPath "$root/work/lab-instances/$q/coop-status.json$suffix" -Destination "$out/$q$suffix" -ErrorAction Stop}catch{}}}
  $last=$tries[$tries.Count-1]
  if(!$hurt){throw "The grenade did not hurt the guard in $($tries.Count) throws (host $($last.before.host) -> $($last.after.host))"}
  $row.checks.Add("Host grenade hurt the bound guard: host $($last.before.host) -> $($last.after.host), client $($last.before.client) -> $($last.after.client)")
  $deadHost=($null-eq$last.after.host)-or[double]$last.after.host-le0;$deadClient=($null-eq$last.after.client)-or[double]$last.after.client-le0
  if($deadHost-ne$deadClient){throw "Guard dead in one world only (host $($last.after.host), client $($last.after.client))"}
  if(!$deadHost-and$last.after.host-ne$last.after.client){throw "Guard health differs (host $($last.after.host), client $($last.after.client))"}
  $row.checks.Add($(if($deadHost){'Guard dead in both worlds'}else{"Guard health equal in both worlds ($($last.after.host))"}))
  $row.passed=$true
 }catch{$row.failure=$_.Exception.Message}
 foreach($c in @($captures)){try{if(!$c.HasExited){Stop-Process -Id $c.Id}}catch{}}
 try{Restore 'grenade';$row.restored=$true}catch{$row.restored=$false;$row.failure=(("$($row.failure); restore: "+$_.Exception.Message)).TrimStart('; ')}
 $rows.Add([pscustomobject]$row);Save "$out/grenade.json" ([pscustomobject]$row)
 if(!$row.restored){throw 'Fixture restore failed'}
 $dirty=$false'''
end = lines[tail:]
end = [l.replace("operation='PairedVictim1248l'", "operation='GrenadeBoundGuard1273'") for l in end]
out = nl.join(head + setup + body.split('\n') + end)
def rep(old, new):
    global out
    assert out.count(old) == 1, old[:70]; out = out.replace(old, new)
rep("scope='paired_victim_alignment: rear choke under the product controller (NPC stream on, natural guard AI), both source roles; partner phases and the observer-world victim recorded; fixture restored after every case.'",
    "scope='Stage 4 host grenade on a combat-bound guard: under the product controller the host throws one native grenade at the Dunwall tutorial guard; the guard must be hurt and end in the same state in both worlds (1214w native pass, HostWorld/Dead); fixture restored.'")
rep('"PASS_PAIRED_VICTIM $($rows.Count) cases"', '"PASS_GRENADE_BOUND_GUARD"')
rep('$failure="$($bad.Count) case(s) failed: "+(($bad|ForEach-Object {"$($_.source)-$($_.kind): $($_.failure)"})-join \' | \')', '$failure=($bad|ForEach-Object {$_.failure})-join \' | \'')
P.joinpath('Test-GrenadeBoundGuard-v1273.ps1').write_bytes(out.encode('utf-8'))
print('ok')
